/* ==============================================================================
   Venus Design System — Token System
   ============================================================================== */

:root {
  /* ===== Brand Colors (Light Mode) ===== */
  --brand-1: #f8f7fd;
  --brand-2: #e9e7f8;
  --brand-3: #d6d2f4;
  --brand-4: #c7c1f0;
  --brand-5: #b8b1ed;
  --brand-6: #9f95ef;
  --brand-7: #8f83ec;
  --brand-8: #7b6de9;
  --brand-9: #6b5be6;
  --brand-10: #3721de;
  --brand-11: #2919a4;
  --brand-12: #1c1263;

  /* ===== Neutral Scale (Light) ===== */
  --gray-1: #fcfcfc;
  --gray-2: #f9f9f9;
  --gray-3: #f0f0f0;
  --gray-4: #e4e4e7;
  --gray-5: #d4d4d8;
  --gray-6: #a1a1aa;
  --gray-7: #71717a;
  --gray-8: #52525b;
  --gray-9: #3f3f46;
  --gray-10: #27272a;
  --gray-11: #18181b;
  --gray-12: #09090b;

  /* ===== Semantic Colors (Light Mode) — HSL for shadcn compatibility ===== */
  --background: 0 0% 100%;
  --background-secondary: 0 0% 100%;
  --foreground: 210 14% 12%;
  --card: 0 0% 100%;
  --card-foreground: 210 14% 12%;
  --popover: 0 0% 100%;
  --popover-foreground: 210 14% 12%;

  /* Navigation backgrounds (hex — not used by Tailwind) */
  --nav-background: #ffffff;
  --nav-background-expanded: #fafafa;

  --primary: 247 74% 63%;
  --primary-foreground: 0 0% 100%;
  --secondary: 251 73% 89%;
  --secondary-foreground: 240 5% 26%;
  --muted: 251 73% 89%;
  --muted-foreground: 0 0% 45%;
  --accent: 251 66% 85%;
  --accent-foreground: 247 74% 63%;
  --destructive: 0 84% 60%;
  --destructive-foreground: 0 0% 100%;
  --border: 240 6% 90%;
  --input: 0 0% 94%;
  --ring: 247 74% 67%;

  /* Danger */
  --danger-50: #fee2e2;
  --danger-100: #fee2e2;
  --danger-200: #fee2e2;
  --danger-300: #fca5a5;
  --danger-400: #f87171;
  --danger-500: #ef4444;
  --danger-600: #dc2626;
  --danger-700: #dc2626;
  --danger-800: #991b1b;
  --danger-900: #7f1d1d;
  --danger-fg: #ffffff;

  /* Success */
  --success-50: #d1fae5;
  --success-100: #d1fae5;
  --success-200: #bbf7d0;
  --success-300: #86efac;
  --success-400: #4ade80;
  --success-500: #10b981;
  --success-600: #047857;
  --success-700: #047857;
  --success-800: #166534;
  --success-900: #14532d;
  --success-fg: #0a0a0b;

  /* Info */
  --info-50: #dbeafe;
  --info-100: #dbeafe;
  --info-200: #bfdbfe;
  --info-300: #93c5fd;
  --info-400: #60a5fa;
  --info-500: #3b82f6;
  --info-600: #1d4ed8;
  --info-700: #1d4ed8;
  --info-800: #1e40af;
  --info-900: #1e3a8a;
  --info-fg: #ffffff;

  /* Warning */
  --warning-50: #fef3c7;
  --warning-100: #fef3c7;
  --warning-200: #fde68a;
  --warning-300: #fcd34d;
  --warning-400: #fbbf24;
  --warning-500: #f59e0b;
  --warning-600: #d97706;
  --warning-700: #d97706;
  --warning-800: #92400e;
  --warning-900: #78350f;
  --warning-fg: #0a0a0b;

  /* Badge Colors — Purple */
  --badge-purple-50: #faf5ff;
  --badge-purple-100: #f3e8ff;
  --badge-purple-200: #e9d5ff;
  --badge-purple-300: #d8b4fe;
  --badge-purple-400: #c084fc;
  --badge-purple-500: #a855f7;
  --badge-purple-600: #9333ea;
  --badge-purple-700: #7e22ce;
  --badge-purple-800: #6b21a8;
  --badge-purple-900: #581c87;
  --badge-purple-fg: #ffffff;

  /* Badge Colors — Blue */
  --badge-blue-50: #eff6ff;
  --badge-blue-100: #dbeafe;
  --badge-blue-200: #bfdbfe;
  --badge-blue-300: #93c5fd;
  --badge-blue-400: #60a5fa;
  --badge-blue-500: #3b82f6;
  --badge-blue-600: #2563eb;
  --badge-blue-700: #1d4ed8;
  --badge-blue-800: #1e40af;
  --badge-blue-900: #1e3a8a;
  --badge-blue-fg: #ffffff;

  /* Badge Colors — Green */
  --badge-green-50: #f0fdf4;
  --badge-green-100: #dcfce7;
  --badge-green-200: #bbf7d0;
  --badge-green-300: #86efac;
  --badge-green-400: #4ade80;
  --badge-green-500: #22c55e;
  --badge-green-600: #16a34a;
  --badge-green-700: #15803d;
  --badge-green-800: #166534;
  --badge-green-900: #14532d;
  --badge-green-fg: #0a0a0b;

  /* Badge Colors — Orange */
  --badge-orange-50: #fff7ed;
  --badge-orange-100: #ffedd5;
  --badge-orange-200: #fed7aa;
  --badge-orange-300: #fdba74;
  --badge-orange-400: #fb923c;
  --badge-orange-500: #f97316;
  --badge-orange-600: #ea580c;
  --badge-orange-700: #c2410c;
  --badge-orange-800: #9a3412;
  --badge-orange-900: #7c2d12;
  --badge-orange-fg: #0a0a0b;

  /* ===== Chart Colors (Light Mode) ===== */
  --chart-rose: #e85a8f;
  --chart-orange: #e88a5a;
  --chart-yellow: #e8d85a;
  --chart-lime: #b0e85a;
  --chart-emerald: #5ae8a0;
  --chart-sky: #5a9ae8;
  --chart-blue: #5a5ae8;
  --chart-indigo: #8a5ae8;
  --chart-purple: #d85ae8;
  --chart-slate: #27272a;
  --chart-gray: #e4e4e7;

  /* Chart colors - using design tokens where possible */
  --chart-1: #8d70ef; /* TODO: Could use primary variation */
  --chart-2: #3b82f6; /* Using info blue */
  --chart-3: #48d1a0; /* TODO: Could use success variation */
  --chart-4: #c478b9; /* TODO: Add accent pink token */
  --chart-5: #7dd3fc; /* TODO: Add accent light blue token */

  /* Gradient variables for animations */
  --gradient-from: var(--searchaf-4);
  --gradient-to: var(--searchaf-5);

  /* Glow effect variables */
  --glow-color-1: var(--searchaf-4);
  --glow-color-2: var(--searchaf-5);
}

/* Dark Mode */
.dark {
  /* ===== Brand Colors (Dark Mode) ===== */
  --brand-1: #0a0721;
  --brand-2: #130e3f;
  --brand-3: #1a115f;
  --brand-4: #23177d;
  --brand-5: #2818a0;
  --brand-6: #2e1cba;
  --brand-7: #3620d9;
  --brand-8: #4f3ce2;
  --brand-9: #6b5be6;
  --brand-10: #8b7eec;
  --brand-11: #aba2f1;
  --brand-12: #cec9f2;

  /* ===== Neutral Scale (Dark) ===== */
  --gray-1: #0a0a0a;
  --gray-2: #0f0f0f;
  --gray-3: #131313;
  --gray-4: #262626;
  --gray-5: #3a3a3a;
  --gray-6: #525252;
  --gray-7: #737373;
  --gray-8: #a1a1a1;
  --gray-9: #d4d4d4;
  --gray-10: #e5e5e5;
  --gray-11: #f5f5f5;
  --gray-12: #ffffff;

  /* ===== Semantic Colors (Dark Mode) — HSL for shadcn compatibility ===== */
  --background: 0 0% 7%;
  --background-secondary: 0 0% 6%;
  --foreground: 210 10% 94%;
  --card: 0 0% 6%;
  --card-foreground: 210 10% 94%;
  --popover: 0 0% 6%;
  --popover-foreground: 210 10% 94%;

  /* Navigation backgrounds (hex — not used by Tailwind) */
  --nav-background: #131313;
  --nav-background-expanded: #0f0f0f;

  --primary: 247 74% 63%;
  --primary-foreground: 0 0% 100%;
  --secondary: 240 4% 16%;
  --secondary-foreground: 210 10% 94%;
  --muted: 240 4% 16%;
  --muted-foreground: 215 16% 57%;
  --accent: 247 50% 25%;
  --accent-foreground: 247 74% 75%;
  --destructive: 0 84% 60%;
  --destructive-foreground: 0 0% 100%;
  --border: 240 4% 18%;
  --input: 240 4% 18%;
  --ring: 247 74% 63%;

  /* Danger (Dark Mode) */
  --danger-50: #1a0808;
  --danger-100: #2a0f0f;
  --danger-200: #3d1515;
  --danger-300: #5c1e1e;
  --danger-400: #7c2626;
  --danger-500: #ef4444;
  --danger-600: #dc2626;
  --danger-700: #dc2626;
  --danger-800: #fecaca;
  --danger-900: #fee2e2;
  --danger-fg: #ffffff;

  /* Success (Dark Mode) */
  --success-50: #0a1a0c;
  --success-100: #0f2a12;
  --success-200: #153d19;
  --success-300: #1e5c24;
  --success-400: #267c32;
  --success-500: #10b981;
  --success-600: #047857;
  --success-700: #047857;
  --success-800: #bbf7d0;
  --success-900: #d1fae5;
  --success-fg: #ffffff;

  /* Info (Dark Mode) */
  --info-50: #081a2a;
  --info-100: #0f2544;
  --info-200: #1e3a5f;
  --info-300: #2c5282;
  --info-400: #3c6cb4;
  --info-500: #3b82f6;
  --info-600: #1d4ed8;
  --info-700: #1d4ed8;
  --info-800: #bfdbfe;
  --info-900: #dbeafe;
  --info-fg: #ffffff;

  /* Warning (Dark Mode) */
  --warning-50: #1a1508;
  --warning-100: #2a220f;
  --warning-200: #3d3015;
  --warning-300: #5c4a1e;
  --warning-400: #7c6426;
  --warning-500: #f59e0b;
  --warning-600: #d97706;
  --warning-700: #d97706;
  --warning-800: #fde68a;
  --warning-900: #fef3c7;
  --warning-fg: #ffffff;

  /* Badge Colors — Purple (Dark Mode) */
  --badge-purple-50: #1a0b2e;
  --badge-purple-100: #2e1a47;
  --badge-purple-200: #4a2766;
  --badge-purple-300: #6b3398;
  --badge-purple-400: #8b4cc9;
  --badge-purple-500: #a855f7;
  --badge-purple-600: #c084fc;
  --badge-purple-700: #d8b4fe;
  --badge-purple-800: #e9d5ff;
  --badge-purple-900: #f3e8ff;
  --badge-purple-fg: #ffffff;

  /* Badge Colors — Blue (Dark Mode) */
  --badge-blue-50: #0a1929;
  --badge-blue-100: #1e2a3f;
  --badge-blue-200: #2d3e5f;
  --badge-blue-300: #3d5687;
  --badge-blue-400: #5577b5;
  --badge-blue-500: #3b82f6;
  --badge-blue-600: #60a5fa;
  --badge-blue-700: #93c5fd;
  --badge-blue-800: #bfdbfe;
  --badge-blue-900: #dbeafe;
  --badge-blue-fg: #ffffff;

  /* Badge Colors — Green (Dark Mode) */
  --badge-green-50: #0a1f0f;
  --badge-green-100: #1a332a;
  --badge-green-200: #2a4d3f;
  --badge-green-300: #3d7059;
  --badge-green-400: #559373;
  --badge-green-500: #22c55e;
  --badge-green-600: #4ade80;
  --badge-green-700: #86efac;
  --badge-green-800: #bbf7d0;
  --badge-green-900: #dcfce7;
  --badge-green-fg: #ffffff;

  /* Badge Colors — Orange (Dark Mode) */
  --badge-orange-50: #1a0f08;
  --badge-orange-100: #2e1f15;
  --badge-orange-200: #4d3322;
  --badge-orange-300: #734a2f;
  --badge-orange-400: #99653f;
  --badge-orange-500: #f97316;
  --badge-orange-600: #fb923c;
  --badge-orange-700: #fdba74;
  --badge-orange-800: #fed7aa;
  --badge-orange-900: #ffedd5;
  --badge-orange-fg: #ffffff;

  /* ===== Chart Colors (Dark Mode) ===== */
  --chart-rose: #c45a8f;
  --chart-orange: #c48a5a;
  --chart-yellow: #c4c05a;
  --chart-lime: #a0c45a;
  --chart-emerald: #5ac490;
  --chart-sky: #5a8ac4;
  --chart-blue: #5a5ac4;
  --chart-indigo: #805ac4;
  --chart-purple: #c45ac4;
  --chart-slate: #f0f0f0;
  --chart-gray: #3f3f46;

  --chart-1: #a78bfa; /* TODO: Could use primary variation */
  --chart-2: #60a5fa; /* Using info blue */
  --chart-3: #5be4b3; /* TODO: Could use success variation */
  --chart-4: #d48bcc; /* TODO: Add accent pink token */
  --chart-5: #93e5ff; /* TODO: Add accent light blue token */

  /* Dark mode glow variables */
  --glow-color-1: var(--searchaf-6);
  --glow-color-2: var(--searchaf-7);
}

/* ==============================================================================
   Tailwind @theme — Design Tokens → Utility Classes
   ============================================================================== */

@theme {
  /* ===== Primary Brand ===== */
  --color-primary: #6c5ce7;
  --color-primary-hover: #5f51d8;
  --color-primary-active: #5445c9;
  --color-primary-light: #f5f3ff;
  --color-primary-lighter: #fafafe;
  --color-primary-subtle: #f0edfc;
  --color-primary-muted: #e8e4fc;

  /* ===== Surface Colors ===== */
  --color-surface-purple: #f9f8ff;
  --color-surface-blue: #f1f6ff;
  --color-surface-gray: #f7f9fc;

  /* ===== Accent ===== */
  --color-accent-blue: #6b7cf2;

  /* ===== Gray Scale ===== */
  --color-gray-50: #fafbfc;
  --color-gray-100: #f7f9fc;
  --color-gray-200: #eff2f7;
  --color-gray-300: #e3e8ef;
  --color-border: #e5e7eb;
  --color-border-hover: #3b4555;
  --color-gray-400: #cbd5e0;
  --color-gray-500: #a0aec0;
  --color-gray-600: #718096;
  --color-body: #6b7280;
  --color-heading: #475161;
  --color-gray-800: #2d3748;
  --color-title: #111827;
  --color-gray-900: #1a202c;

  /* ===== Text Colors ===== */
  --color-ink: #222222;
  --color-subtle: #647696;
  --color-placeholder: #a9b6cb;
  --color-hint: #767676;

  /* ===== Form Colors ===== */
  --color-input-border: #dde3ee;

  /* ===== Status Colors ===== */
  --color-success: #10b981;
  --color-success-light: #d1fae5;
  --color-success-dark: #047857;

  --color-warning: #f59e0b;
  --color-warning-light: #fef3c7;
  --color-warning-dark: #d97706;

  --color-danger: #ef4444;
  --color-danger-light: #fee2e2;
  --color-danger-dark: #dc2626;

  --color-info: #3b82f6;
  --color-info-light: #dbeafe;
  --color-info-dark: #1d4ed8;

  /* Status Pill — Live/Published */
  --color-status-live: #007a52;
  --color-status-live-bg: #f5fffc;

  /* ===== Category Colors (Targeting UI) ===== */
  --color-category-audience: #4299e1;
  --color-category-audience-bg: #ebf5ff;
  --color-category-device-bg: #ecfdf5;
  --color-category-location-bg: #fff7ed;
  --color-category-time-bg: #faf5ff;

  /* ===== Additional Accent Colors ===== */
  --color-orange: #f97316;
  --color-purple: #a855f7;

  /* ===== Pill Border Colors ===== */
  --color-pill-warning-border: #fde68a;
  --color-pill-success-border: #a7f3d0;
  --color-pill-danger-border: #fecaca;
  --color-pill-default-border: #d1d5db;

  /* ===== Interactive States ===== */
  --color-focus-ring: rgb(108 92 231 / 0.5);
  --color-link: #6c5ce7;
  --color-link-hover: #5445c9;

  /* ===== Spacing Scale (4px base) ===== */
  --spacing-0: 0;
  --spacing-1: 4px;
  --spacing-2: 8px;
  --spacing-2-5: 10px;
  --spacing-3: 12px;
  --spacing-4: 16px;
  --spacing-5: 20px;
  --spacing-6: 24px;
  --spacing-8: 32px;
  --spacing-10: 40px;
  --spacing-12: 48px;
  --spacing-16: 64px;
  --spacing-20: 80px;

  /* Layout spacing */
  --spacing-card-x: 16px;
  --spacing-page: 24px;
  --spacing-page-top: 32px;
  --spacing-page-x: 32px;
  --spacing-section: 24px;
  --spacing-card-gap: 16px;

  /* ===== Typography ===== */
  --font-sans:
    "Inter", -apple-system, BlinkMacSystemFont, "Segoe UI", "Roboto", "Helvetica Neue", Arial,
    sans-serif;
  --font-mono: "SF Mono", Menlo, Monaco, "Courier New", monospace;

  --font-size-xs: 12px;
  --font-size-sm: 14px;
  --font-size-base: 16px;
  --font-size-lg: 18px;
  --font-size-xl: 20px;
  --font-size-2xl: 24px;
  --font-size-3xl: 30px;
  --font-size-4xl: 36px;

  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  --line-height-tight: 1.25;
  --line-height-snug: 1.375;
  --line-height-normal: 1.5;
  --line-height-relaxed: 1.625;
  --line-height-loose: 2;

  --letter-spacing-tighter: -0.05em;
  --letter-spacing-tight: -0.025em;
  --letter-spacing-normal: 0;
  --letter-spacing-wide: 0.025em;
  --letter-spacing-wider: 0.05em;

  /* ===== Shadows ===== */
  --shadow-xs: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-sm: 0 1px 3px 0 rgb(0 0 0 / 0.1), 0 1px 2px 0 rgb(0 0 0 / 0.06);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -1px rgb(0 0 0 / 0.06);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -2px rgb(0 0 0 / 0.05);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 10px 10px -5px rgb(0 0 0 / 0.04);
  --shadow-2xl: 0 25px 50px -12px rgb(0 0 0 / 0.25);
  --shadow-focus: 0 0 0 3px rgb(108 92 231 / 0.1);
  --shadow-inner: inset 0 2px 4px 0 rgb(0 0 0 / 0.06);
  --shadow-input-focus: inset 0 0 0 1px #6c5ce7;

  /* ===== Border Radius ===== */
  --radius-none: 0;
  --radius-sm: 4px;
  --radius-md: 6px;
  --radius-lg: 8px;
  --radius-xl: 12px;
  --radius-2xl: 16px;
  --radius-full: 9999px;

  /* ===== Border Widths ===== */
  --border-width-0: 0;
  --border-width-1: 1px;
  --border-width-2: 2px;
  --border-width-4: 4px;

  /* ===== Transitions ===== */
  --duration-75: 75ms;
  --duration-100: 100ms;
  --duration-150: 150ms;
  --duration-200: 200ms;
  --duration-300: 300ms;
  --duration-500: 500ms;
  --duration-700: 700ms;
  --duration-1000: 1000ms;

  --ease-linear: linear;
  --ease-in: cubic-bezier(0.4, 0, 1, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);

  /* ===== Z-Index ===== */
  --z-0: 0;
  --z-10: 10;
  --z-20: 20;
  --z-30: 30;
  --z-40: 40;
  --z-50: 50;
  --z-modal: 100;
  --z-toast: 200;
  --z-tooltip: 300;
}

/* ==============================================================================
   Component-Specific Tokens
   ============================================================================== */

:root {
  /* Button */
  --button-height-sm: 32px;
  --button-height-md: 40px;
  --button-height-lg: 44px;
  --button-font-size-sm: 14px;
  --button-font-size-md: 16px;
  --button-font-size-lg: 16px;
  --button-font-weight: 600;
  --button-border-radius: 4px;

  /* Input */
  --input-height-sm: 32px;
  --input-height-md: 40px;
  --input-height-lg: 44px;
  --input-font-size-sm: 14px;
  --input-font-size-md: 16px;
  --input-font-size-lg: 16px;
  --input-border-radius: 4px;
  --input-border-width: 1px;

  /* Card */
  --card-padding-x: var(--spacing-card-x);
  --card-padding-y: var(--spacing-6);
  --card-border-color: var(--color-border);
  --card-border-hover: var(--color-border-hover);
  --card-border-radius: var(--radius);
  --card-icon-bg: var(--color-surface-purple);
  --card-title-color: var(--color-title);
  --card-description-color: var(--color-body);

  /* Icon Container */
  --icon-container-size: var(--spacing-10);
  --icon-size: 24px;

  /* Layout */
  --page-padding: var(--spacing-page);
  --page-padding-top: var(--spacing-page-top);
  --page-padding-x: var(--spacing-page-x);
  --section-gap: var(--spacing-section);
  --card-grid-gap: var(--spacing-card-gap);
}

/* ==============================================================================
   Utility Classes
   ============================================================================== */

/* Text colors */
.text-title {
  color: var(--color-title);
}
.text-heading {
  color: var(--color-heading);
}
.text-body {
