/* Venus Table Component Styles */

/* Sticky column shadow effect - borders handled by normal Tailwind classes */
.venus-table-sticky-shadow {
  position: sticky; /* Maintain sticky behavior while creating positioning context */
}

.venus-table-sticky-shadow::before {
  content: "";
  position: absolute;
  left: -10px;
  top: 0;
  bottom: 0;
  width: 10px;
  background: linear-gradient(to left, rgba(0, 0, 0, 0.05), transparent);
  pointer-events: none;
}

.dark .venus-table-sticky-shadow::before {
  background: linear-gradient(to left, rgba(255, 255, 255, 0.05), transparent);
}

